import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"45、【萃】 坤下兑上","description":"子夏易传 - 45、【萃】 坤下兑上","frontmatter":{"title":"45、【萃】 坤下兑上","description":"子夏易传 - 45、【萃】 坤下兑上"},"headers":[],"relativePath":"zh/classics/zixia/047.md","filePath":"zh/classics/zixia/047.md"}'),i={name:"zh/classics/zixia/047.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_45、【萃】-坤下兑上" tabindex="-1">45、【萃】 坤下兑上 <a class="header-anchor" href="#_45、【萃】-坤下兑上" aria-label="Permalink to “45、【萃】 坤下兑上”">​</a></h1><p>卦辞：萃，亨。王假有廟，利見大人亨。利貞。用大牲吉。利有攸往。</p><p>彖曰：萃，聚也。順以説。剛中而應，故聚也。王假有廟，致孝享也。利見大人亨，聚以正也。用大牲吉，利有攸往，順天命也。觀其所聚而天地萬物之情可見矣。</p><p>子夏：順而以説，柔无違也。剛中正而應，保其萃以通也。天下大聚，正者而孝享，聚其昭穆，剛尊而利以見也。萃其正而通也。用大牲吉，聚而豐之，得其稱也。夫聚而通之。何往不利。順於類正而相聚得其通，而保其久也。天地萬物之情見於此矣。</p><p>象曰：澤上於地，萃。君子以除戎器，戒不虞。</p><p>澤得地以久，地得澤以潤相，聚之道也。衆之聚也，不可以无防，故君子以除戎器，戒不虞。</p><p>初六，有孚不終，乃亂乃萃，若號，一握為笑，勿恤，往无咎。</p><p>象曰：乃亂乃萃，其志亂也。</p><p>子夏：四為上應，三近附之，已信不終，失其萃矣。則心惑而志亂矣。何所利哉。若小能號呼，自省度其可否，反而哂之不以為笑，靜然保居，終獲其應，復何憂哉。往必无咎也。</p><p>六二，引吉无咎，孚乃利用禴。</p><p>象曰：引吉无咎，中未變也。</p><p>子夏：初三皆萃於四，已獨守中，不變其志，待於五，牽而後為聚，得其吉矣。居内靡他，何咎之有。精意承奉信以結之，豈待於豐乎，雖薄而可以薦也。</p><p>六三，萃如，嗟如，无攸利，往无咎，小吝。</p><p>象曰：往无咎，上巽也。</p><p>子夏：下皆上，萃。已无應焉。萃如，嗟如也，何所利哉。奉於四剛，剛巽而與，故往而无咎。不能下已而從人，位之失矣，可小惜也。</p><p>九四，大吉无咎。</p><p>象曰：大吉无咎，位不當也。</p><p>子夏：承上於地以剛處之，而下據其衆，非其至公奉上之心大吉則咎也。</p><p>九五，萃有位，无咎。匪孚，元永貞，悔亡。</p><p>象曰：萃有位，志未光也。</p><p>子夏：四有其民，而權逼於已，位當貴也，咎何有乎。尊信不行，道豈光乎，且陽徳仁也，可以長正而悔亡矣，民終歸之也。</p><p>上六，齎咨涕洟，无咎。</p><p>象曰：齎咨涕洟，未安上也。</p><p>子夏：乘剛而不安，違而无萃。齎咨憂嘆以至於涕洟，懼而内戒，咎何有焉。</p>',24)])])}const m=a(i,[["render",r]]);export{h as __pageData,m as default};
